import re, collections
p='/workspace/logs/wandb/offline-run-20260926_105216-l7my3znq/files/output.log'
lines=open(p,errors='replace').read().splitlines()
blocks=[]
cur=None
for ln in lines:
    if ln.startswith('[TACO-FAIL]'):
        if cur: blocks.append(cur)
        cur={'hdr':ln}
    elif cur is not None:
        if ln.startswith('===') or ln.startswith('step:'):
            blocks.append(cur); cur=None
        else:
            m=re.match(r'^\[(question|error|code|input|expected|output|TACO-FAIL)\]\s?(.*)$',ln)
            if m: cur[m.group(1)]=m.group(2)
if cur: blocks.append(cur)
print('n blocks', len(blocks))
print(collections.Counter(b.get('TACO-FAIL') for b in blocks))
# parse header fields
def field(h,k):
    m=re.search(k+r'=(\S+)',h); return m.group(1) if m else None
print('split',collections.Counter(field(b['hdr'],'split') for b in blocks))
print('code_type',collections.Counter(field(b['hdr'],'code_type') for b in blocks))
print('n_pass/n_tests',collections.Counter(field(b['hdr'],'n_pass/n_tests') for b in blocks).most_common(15))
outs=collections.Counter('empty' if b.get('output','').strip() in ('[]','None','') else 'nonempty' for b in blocks)
print('output state',outs)
errs=collections.Counter(b.get('error','(none)')[:60] for b in blocks)
print('errors top',errs.most_common(15))
# examples with nonempty output
cnt=0
for b in blocks:
    if b.get('output','').strip() not in ('[]','None','') and cnt<5:
        print('---- example nonempty')
        for k in ['TACO-FAIL','question','error','code','input','expected','output']:
            print(k,':',(b.get(k,'') or '')[:300])
        cnt+=1
EOF

