arguments.command:
cd /tmp && python3 - <<'EOF'
import re, collections
p='/workspace/logs/wandb/offline-run-20260926_105216-l7my3znq/files/output.log'
lines=open(p,errors='replace').read().splitlines()
blocks=[]; cur=None
for ln in lines:
    if ln.startswith('[TACO-FAIL]'):
        if cur: blocks.append(cur)
        cur={'hdr':ln,'lines':[]}
    elif cur is not None:
        if ln.startswith('===') or ln.startswith('step:'):
            blocks.append(cur); cur=None
        else:
            cur['lines'].append(ln)
if cur: blocks.append(cur)
def field(t,k):
    m=re.search(k+r'=(\S+)',t); return m.group(1) if m else None
# each hdr followed by a line with problem_id...
recs=[]
for b in blocks:
    txt='\n'.join(b['lines'])
    f={}
    m=re.search(r'problem_id=(\S+) code_type=(\S+) fn_name=(\S+)',txt)
    if m: f=dict(zip(['pid','ct','fn'],m.groups()))
    m=re.search(r'n_pass/n_tests=(\S+) fail_index=(\S+) result=(\S+)',txt)
    if m: f.update(dict(zip(['npnt','fi','res'],m.groups())))
    m=re.search(r'^\[error\] (.*)$',txt,re.M)
    if m: f['err']=m.group(1)
    m=re.search(r'^\[output\] (.*)$',txt,re.M)
    f['out']=m.group(1) if m else None
    m=re.search(r'^\[expected\] (.*)$',txt,re.M)
    f['exp']=m.group(1) if m else None
    m=re.search(r'^\[input\] (.*)$',txt,re.M)
    f['inp']=m.group(1) if m else None
    recs.append(f)
print('parsed',len(recs),'with pid',sum(1 for r in recs if 'pid' in r))
print('ct',collections.Counter(r.get('ct') for r in recs))
print('ct x emptyout',collections.Counter((r.get('ct'), 'empty' if (r.get('out') or '').strip() in ('[]','None','') else 'nonempty') for r in recs))
print('npnt',collections.Counter(r.get('npnt') for r in recs).most_common(12))
print('err x ct',collections.Counter((r.get('err','(none)')[:25],r.get('ct')) for r in recs).most_common(20))
# show empty-output call_based cases
n=0
for r in recs:
    if r.get('ct')=='call_based' and (r.get('out') or '').strip() in ('[]','None','') and n<6:
        print('---',r); n+=1
n=0
