import pyarrow.parquet as pq, glob, pyarrow.compute as pc, json
files=sorted(glob.glob('/autorlbench/datasets/BAAI__TACO/ALL/train-*.parquet'))
targets=['findXY','is_anagram','is_common','minimum_Number']
found={t:None for t in targets}
for f in files:
    pf=pq.ParquetFile(f)
    for batch in pf.iter_batches(batch_size=50000, columns=['name','starter_code','input_output','difficulty']):
        sc=batch.column('starter_code').to_pylist()
        io=batch.column('input_output').to_pylist()
        for i,s in enumerate(sc):
            for t in targets:
                if found[t] is None and s and t in s:
                    found[t]={'file':f,'starter':s[:200],'io':io[i][:600]}
        if all(v is not None for v in found.values()): break
    if all(v is not None for v in found.values()): break
for t,v in found.items():
    print('====',t)
    print(v)
EOF

